contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value);

        c.withdrawAll(); if (__ESBMC_reverted()) return;
        c.sendMoney(address(c), value); if (__ESBMC_reverted()) return;

        uint fundedC = address(c).balance;
        uint fundedThis = address(this).balance;

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        assert(fundedC >= value ?
            (!reverted && afterC == fundedC - value && afterThis == fundedThis + value) :
            (reverted && afterC == fundedC && afterThis == fundedThis));
    }
}

