// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= value);
        try c.withdrawAll() {} catch { return; }
        try c.sendMoney(address(c), value) {} catch { return; }
        uint fundedC = address(c).balance;
        uint fundedThis = address(this).balance;
        bool reverted;
        try c.withdraw(value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        assertTrue(fundedC >= value ?
            (!reverted && afterC == fundedC - value && afterThis == fundedThis + value) :
            (reverted && afterC == fundedC && afterThis == fundedThis));
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable {}
}
